const out = [];
const TARGET_NPA = ['1630', '1635'];
const TARGET_LOC = /^(bulle|la tour-de-tr[eê]me)$/i;

// --- Gruyère Immo (JSON API) ---
let gy = null;
try { gy = $('Fetch Gruyere API').first().json; } catch (e) { gy = null; }
if (!gy || gy.status !== 'success' || !Array.isArray(gy.results) || gy.results.length === 0) {
  throw new Error('gruyere-immo: /api/properties returned no usable results — API changed or blocked');
}
const stripHtml = s => (s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const chf = s => { const m = String(s ?? '').match(/([\d']+)/); return m ? parseInt(m[1].replace(/'/g, ''), 10) : null; };
for (const r of gy.results) {
  if (!/louer/i.test(r.transaction || '')) continue;
  if (!TARGET_NPA.includes(String(r.npa))) continue;
  const rooms = parseFloat(r.pieces);
  if (isNaN(rooms) || rooms < 2.5 || rooms > 3.5) continue;
  const net = chf(r.prix);
  const gross = chf(r.loyerBrut);
  out.push({ json: {
    source: 'gruyere-immo',
    source_id: r.slug,
    url: 'https://www.gruyere-immo.ch/details-d-un-bien-immobilier/' + r.slug,
    title: (r.titre || 'Appartement') + ' — ' + (r.adresse ? r.adresse + ', ' : '') + r.npa + ' ' + r.localite,
    rent_net: net, rent_gross: gross, charges: chf(r.charges),
    rooms, m2: r.surface ? Number(r.surface) : null,
    commune: r.localite, address_raw: r.adresse || null,
    description: stripHtml(r.desc).slice(0, 900),
    cross_key: null, published_at: r.dateCreation ? r.dateCreation.replace(' ', 'T') + '+02:00' : null,
    images: Array.isArray(r.photos) ? r.photos.slice(0, 3) : (r.photo ? [r.photo] : [])
  }});
}

// --- Sallin Immobilier (HTML) ---
let sallinHtml = '';
try { sallinHtml = $('Fetch Sallin').first().json.data || ''; } catch (e) { sallinHtml = ''; }
if (typeof sallinHtml !== 'string' || !sallinHtml.includes('data-object-id=')) {
  throw new Error('sallin: no object cards on /a-louer — page structure changed or request blocked');
}
const decode = s => (s || '').replace(/&#(\d+);/g, (_, c) => String.fromCharCode(c)).replace(/&amp;/g, '&').replace(/&#039;|&apos;/g, "'").replace(/\s+/g, ' ').trim();
const sSeen = new Set();
for (const b of sallinHtml.split('data-object-id="').slice(1)) {
  const id = (b.match(/^(\d+)/) || [])[1];
  if (!id || sSeen.has(id)) continue;
  sSeen.add(id);
  const href = (b.match(/href="(\/fr\/o\/[^"]+)"/) || [])[1];
  const loc = decode((b.match(/<h3>([^<]+)<\/h3>/) || ['',''])[1]);
  if (!TARGET_LOC.test(loc)) continue;
  const otype = decode((b.match(/<h2>([^<]+)<\/h2>/) || ['',''])[1]);
  const rm = (b.match(/caract_rooms[\s\S]{0,600}?value">\s*([\d.,]+)\s*</) || [])[1];
  const rooms = rm ? parseFloat(rm.replace(',', '.')) : null;
  if (rooms === null || rooms < 2.5 || rooms > 3.5) continue;
  const pm = (b.match(/box_price[\s\S]{0,120}?CHF\s*([\d']+)/) || [])[1];
  const m2m = (b.match(/caract_surface[\s\S]{0,600}?value">\s*~?\s*(\d+)\s*m/) || [])[1];
  const img = (b.match(/src="(https:\/\/www\.immomigimg\.ch\/[^"]+)"/) || [])[1];
  out.push({ json: {
    source: 'sallin',
    source_id: id,
    url: href ? 'https://sallin-immobilier.ch' + href : null,
    title: otype + ' ' + rooms + ' pièces — ' + loc,
    rent_net: null, rent_gross: pm ? parseInt(pm.replace(/'/g, ''), 10) : null, charges: null,
    rooms, m2: m2m ? parseInt(m2m, 10) : null,
    commune: loc, address_raw: null,
    description: otype + ' à ' + loc, cross_key: null, published_at: null,
    images: img ? [img] : []
  }});
}
return out;
